from argparse import ArgumentError
import logging
from ta_measurements.configuration import MeasurementConfiguration
from ta_measurements.measurements import Measurements
from robot.api.deco import keyword
from ute_common_abstract_core.message_query_builder import message_query_parser
from ta_measurements.exceptions import (
    WrongMeasurementType,
    MeasurementsNotStarted,
    TooManyFieldValuesFulfilingQuery,
    TooLittleFieldValuesFulfilingQuery,
    NoActiveMeasurementsOnUe,
)
from ute_common_abstract_core.message import NotFoundKey
from ta_measurements import configuration
from ta_measurements.logger_config import configure_main_logger

SUPPORTED_MEAS_TYPE_TO_CHECK = ["measObject", "reportConfig", "measId"]


class ta_measurements(object):
    """
    Library that follows installed measurements on UE.
    Version 1.2 added support for field 'measObjectToAddModList-v9e0' in RRCConnectionReconfiguration.
    This field is used when 'carrierFreq' field value inside 'measObjectEUTRA' equals 65535 - that value
    means that real cell earfcn is stored under 'carrierFreq-v9e0' of field 'measObjectEUTRA-v9e0'.
    This library silently replaces 'carrierFreq' value with value of 'carrierFreq-v9e0' for that cell.
    This is done to make some checks easier and frees user from writing more code.
    """

    ROBOT_LIBRARY_SCOPE = "TEST CASE"
    ROBOT_LISTENER_API_VERSION = 2

    def __new__(cls, *args, **kwargs):
        if not hasattr(cls, "_instance"):
            cls._instance = super(ta_measurements, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        configure_main_logger()
        self.meas_managers = {}

    def start_observing_measurements(self, ue_alias, technology="4G"):
        """
        Starts following measurement installations of one UE.
        If this method is not called for particular UE, measurements for this UE will not be available.

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :type technology: radio technology, default is 4G
        :returns: None.
        """
        try:
            self.meas_managers[ue_alias]
        except KeyError:
            self.meas_managers[ue_alias] = Measurements(ue_alias, technology)

    def stop_observing_measurements(self, ue_alias=None):
        """
        Stops following measurement installations.
        If using ROBOT FRAMEWORK it is not mandatory to call this method
        as it will be called automatically at the end of test case.
        If used from Python it is needed to call this method to allow threads to safely end.

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :returns: None.
        """
        if not ue_alias:
            for meas_mgr in self.meas_managers.values():
                meas_mgr.stop()
        else:
            try:
                meas_mgr = self.meas_managers[ue_alias]
            except KeyError:
                pass
                # raise Exception("Not observing measurements for '%s' so can not stop" % ue_alias)
            else:
                meas_mgr.stop()

    def configure_measurements_logger(self, reportconfig=None, measobject=None):
        """
        User can configure how much information is dumped during each get_measurement invocation.
        reportconfig/measobject fields may contain a comma-separated list of fields.
        Only those fields will be visible in measurement dump.
        If some report does not contain a field, measId for such measurement will be omit and not printed.
        :param reportConfig: comma separated values, e.g. eventId
        :param measObject: e.g. carrierFreq
        :return:
        """
        if reportconfig is not None:
            reportconfig = [str(logged_val).strip() for logged_val in str(reportconfig).strip().split(",")]
        if measobject is not None:
            measobject = [str(logged_val).strip() for logged_val in str(measobject).strip().split(",")]
        configuration.LOGGER_DETAILS = {"reportConfig": reportconfig, "measObject": measobject}

    def clear_cached_measurements(self, ue_alias=None):
        """
        Clear the history of collected measurements on UE and resets event counter to 0.
        It may be needed when testcase has higher number of measurement reconfigurations and user does not want to
        specify exact measurement reconfiguration number when waiting for next measurements (in case of re-attach or handover)
        :param ue_alias:
        :return:
        """
        if not ue_alias:
            for meas_mgr in self.meas_managers.values():
                meas_mgr.clear_collected_measurements()
        else:
            try:
                meas_mgr = self.meas_managers[ue_alias]
            except KeyError:
                pass
                # raise Exception("Not observing measurements for '%s' so can not stop" % ue_alias)
            else:
                meas_mgr.clear_collected_measurements()

    def get_active_measurements(self, ue_alias, enable_logging=False):
        """
        Returns measurements that are currently installed on UE or raises NoActiveMeasurementsOnUe
        if no measurements were caught. Returned object is of type
        **ta_measurements.configuration.MeasurementConfiguration** and have 3 attributes:

        #.  *measObjects*
        #.  *reportConfigs*
        #.  *measIds*

        These attributes are Python dictionaries where the key corresponds with measObject/reportConfig/measId ID
        and the value is content of this particular measurement, also in dictionary form.

        Robot Framework example::

            Start observing measurements    UE_1
            Run command    attach_ue    id=1
            ${active}=    Get active measurements    UE_1
            Log to console    ${active}

        ta_measurements.configuration.MeasurementConfiguration object at 0x7f6630408fd0 ::

            Log to console    ${active.measObjects}
        {1: {'measObjectId': 1, u'measObjectEUTRA': {u'neighCellConfig': u'0b00', u'carrierFreq': 1400,
        u'allowedMeasBandwidth': u'mbw25', u'presenceAntennaPort1': u'TRUE'}}} ::

            Log to console    ${active.measIds}
        {1: {u'measObjectId': 1, u'measId': 1, u'reportConfigId': 1}, 2: {u'measObjectId': 1, u'measId': 2,
        u'reportConfigId': 2}, 7: {u'measObjectId': 1, u'measId': 7, u'reportConfigId': 3}} ::

            Run command    ue_measurement_send    id=1    meas_id=7    srsrp=10    srsrq=10
            ${active}=    Get active measurements    UE_1
            log to console    ${active.measObjects}
        {1: {'measObjectId': 1, u'measObjectEUTRA': {u'neighCellConfig': u'0b00', u'carrierFreq': 1400,
        u'allowedMeasBandwidth': u'mbw25', u'presenceAntennaPort1': u'TRUE'}}, 2: {'measObjectId': 2,
        u'measObjectEUTRA': {u'neighCellConfig': u'0b00', u'carrierFreq': 3100, u'allowedMeasBandwidth': u'mbw25',
        u'presenceAntennaPort1': u'FALSE'}}} ::

            log to console    ${active.measIds}
        {1: {u'measObjectId': 1, u'measId': 1, u'reportConfigId': 1}, 2: {u'measObjectId': 1, u'measId': 2,
        u'reportConfigId': 2}, 5: {u'measObjectId': 1, u'measId': 5, u'reportConfigId': 4}, 14: {u'measObjectId': 2,
        u'measId': 14, u'reportConfigId': 5}, 15: {u'measObjectId': 2, u'measId': 15, u'reportConfigId': 6}}

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param enable_logging: bool or string, if enabled, print log dump during keyword execution
        :returns: Object containing active measurements installed on UE.
        :raises: **ta_measurements.exceptions.NoActiveMeasurementsOnUe** if no measurements were caught.
        """
        enable_logging = True if str(enable_logging).lower().strip() == "true" else False
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        try:
            measurement = meas_mgr.get_measurement()
            if enable_logging is True:
                print(measurement)
            logging.getLogger("ta_measurements").debug("Current measurements:\n{}".format(measurement))
            return measurement
        except IndexError:
            raise NoActiveMeasurementsOnUe("No measurements yet observed for %s" % ue_alias)

    def get_measurement_installation_history(self, ue_alias, occurrence="all", enable_logging=False):
        """
        Returns all measurements that are and were installed on UE. The object return is a Python list
        containing objects of type **ta_measurements.configuration.MeasurementConfiguration**, where index 0 is the oldest
        measurement installation.

        Robot Framework example::

            ${history}=    Get measurement installation history    ue_alias=UE_1
            Log to console    ${history}
        [<ta_measurements.configuration.MeasurementConfiguration object at 0x7fe9d8578d10>,
        <ta_measurements.configuration.MeasurementConfiguration object at 0x7fe9d8dd4210>] ::

            Log to console    ${history[0].measObjects}
        {1: {'measObjectId': 1, u'measObjectEUTRA': {u'neighCellConfig': u'0b00', u'carrierFreq': 1400,
        u'allowedMeasBandwidth': u'mbw25', u'presenceAntennaPort1': u'TRUE'}}}

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param occurrence: if 'all' specified returns list of all measurements ,
         if int specified, returns snapshot of measurements after int reconfiguration
        :param enable_logging: bool or string, if enabled, print log dump during keyword execution
        :returns: List containing all measurements that were ever installed on UE.
        """
        enable_logging = True if str(enable_logging).lower().strip() == "true" else False
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        measurements = meas_mgr.get_measurement(occurrence=occurrence)
        if isinstance(measurements, MeasurementConfiguration) and enable_logging is True:
            print(measurements)
        return measurements

    def get_measurement_installation_count(self, ue_alias):
        """
        Returns number of measurements that were installed on UE.

        Robot Framework example::

            ${meas_count}=    Get measurement installation count    UE_1
            Log to console    ${meas_count}
        4

        Means that there were 4 RRCConnectionReconfiguration messages with de/installation of measurements in total.

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :returns: int -- number of measurement installation events on UE.
        """
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        return len(meas_mgr.get_measurement(occurrence="all"))

    def save_last_measurement_count(self, ue_alias):
        """
        Saves last measurement count. If measurement is not found saves 0.

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :returns: None.
        """
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        meas_mgr.save_current_event_count()

    def wait_for_next_measurement_after_saved(self, ue_alias, timeout=60):
        """
        Waits for next measurement after the saved count. This method is blocking.
        If save_last_measurement_count was not used, by default saved_count is initialized with 0.
        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param timeout: Maximum time to wait for next measurement installation.
        :returns: None.
        :raises: **ta_measurements.exceptions.NoEventRecorded** on timeout.
        """
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        saved_meas_count = meas_mgr.get_saved_event_count()
        meas_mgr.wait_for_measurement(after_occurrence=saved_meas_count + 1, timeout=timeout)

    def wait_for_next_measurement(self, ue_alias, timeout=60):
        """
        Waits for next measurement (or until timeout). This method is blocking. If measurement is not found within timeout, raises exception.
        Note: It can be vulnerable to race condition, because trigger for new measurement installation is usually also invoked from main thread.
        Only recommended scenario to use this function is to follow the flow, when no additional actions/verifications are performed between
        trigger function call and wait_for_next_measurement call.
        In other cases use save_last_measurement_count / wait_for_next_measurement_after_saved pair to wait for next measurement.

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param timeout: Maximum time to wait for next measurement installation.
        :type timeout: int
        :returns: None.
        :raises: **ta_measurements.exceptions.NoEventRecorded** on timeout.
        """
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        current_meas_count = meas_mgr.total_event_count
        meas_mgr.wait_for_measurement(after_occurrence=current_meas_count + 1, timeout=timeout)

    def wait_for_measurement(self, ue_alias, occurrence=None, timeout=60):
        """
        Waits for number of measurements since begging of test. This method is blocking only if
        number of measurements to wait for is greater than current number of installed measurement.
        If measurement is not found within timeout, raises exception.

        Robot Framework example::

            Create UE alias     alias=UE_1     ue_id=1     id_type=wts

            Start observing measurements    UE_1
            Run command    attach_ue    id=1
            Wait for measurement    ue_alias=UE1    occurrence=1
            Log to console    This will be printed as at least one measurement was installed during attach.

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param occurrence: Number of occurrences to wait for or None.
        :type occurrence: int or None
        :param timeout: Maximum time to wait for specified number of measurement installations.
        :type timeout: int
        :returns: None.
        :raises: **ta_measurements.exceptions.NoEventRecorded** on timeout.
        """
        meas_mgr = self._get_meas_manager_for_ue_alias(ue_alias)
        meas_mgr.wait_for_measurement(after_occurrence=occurrence, timeout=timeout)

    @keyword(r"${expected_num_of_occurrence:\d+} ${meas_type} should exist with ${expression} for ${ue_alias}")
    def check_expression_on_meas_type(self, expected_num_of_occurrence, meas_type, expression, ue_alias):
        """
        Checks user query (using Query language: https://gitlabe1.ext.net.nokia.com/abstract_library/ta_messaging/wikis/query-language)
        on selected number of fields.

        Robot Framework example::

            1 measObject should exist with ((carrierFreq eq 1400) and (neighCellConfig eq '0b00')) for UE_1
            2 reportConfig should exist with ((triggerQuantity eq "rsrp") and (reportQuantity eq "both")) for UE_1
            3 measId should exist with (measObjectId eq 1) for UE_1

        :param expected_num_of_occurrence: Number of repetitions of field name that fulfils query expression.
        :type expected_num_of_occurrence: int
        :param meas_type: One of ['measObject', 'reportConfig', 'measId'].
        :type meas_type: str
        :param expression: Valid Query language expression.
        :type expression: str
        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :returns: **True** if found number of occurrences equals **expected_num_of_occurrence**.
        :raises: **ta_measurements.exceptions.TooLittleFieldValuesFulfilingQuery** if number of occurrences is < than **expected_num_of_occurrence**.
        :raises: **ta_measurements.exceptions.TooManyFieldValuesFulfilingQuery** if number of occurrences is > than **expected_num_of_occurrence**.
        """
        query = message_query_parser().parse(input=expression)["action_result"]
        active_meas = self.get_active_measurements(ue_alias)
        logging.getLogger("ta_measurements").debug("Analyzing measurements:\n{}".format(active_meas))
        meas_to_check = self._get_meas_type_to_check(meas_type, active_meas)
        logging.getLogger("ta_measurements").debug("Analyzing {} measurements:\n{}".format(meas_type, meas_to_check))

        found, _ = self._get_number_of_query_matching_measurements(query, meas_to_check)

        if found == int(expected_num_of_occurrence):
            return True
        elif found < int(expected_num_of_occurrence):
            raise TooLittleFieldValuesFulfilingQuery(
                "Found {found} '{meas_type}' that fulfill expression {expr}. "
                "Expected: {expected}".format(
                    meas_type=meas_type, expr=expression, found=found, expected=expected_num_of_occurrence
                )
            )
        else:
            raise TooManyFieldValuesFulfilingQuery(
                "Found {found} '{meas_type}' that fulfill expression {expr}. "
                "Expected: {expected}".format(
                    meas_type=meas_type, expr=expression, found=found, expected=expected_num_of_occurrence
                )
            )

    @keyword("Get ${field_name} field value from ${meas_type} with ${expression} for ${ue_alias}")
    def get_field_value_from_meas_type_with_expression(self, field_name, meas_type, expression, ue_alias):
        """
        Returns field value that fulfils user query
        (using Query language: https://gitlabe1.ext.net.nokia.com/abstract_library/ta_messaging/wikis/query-language)

        Robot Framework example::

            ${allowedMeasBandwidth}=    Get allowedMeasBandwidth field value from measObject with (carrierFreq eq 1400) for UE_1
            Log to console   ${allowedMeasBandwidth}
        mbw25 ::

            ${measObjectEUTRA}=    Get measObjectEUTRA field value from measObject with (carrierFreq eq 1400) for UE_1
            Log to console   ${measObjectEUTRA}
        {u'allowedMeasBandwidth': u'mbw25',
        u'carrierFreq': 1400,
        u'neighCellConfig': u'0b00',
        u'presenceAntennaPort1': u'TRUE'} ::

            ${reportConfigId}=     Get reportConfigId field value from reportConfig with (eventA3 is present) for UE_1
            Log to console   ${reportConfigId}
        1

        :param field_name: Any valid field name that is present inside parsed measurement message (typically RRCConnectionReconfiguration).
        :type field_name: str
        :param meas_type: One of ['measObject', 'reportConfig', 'measId'].
        :type meas_type: str
        :param expression: Valid Query language expression.
        :type expression: str
        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :returns: **field_name** value if exactly one occurrence of **field_name** inside **meas_type** that fulfils **expression** was found.
        :raises: **ta_measurements.exceptions.TooLittleFieldValuesFulfilingQuery** if number of occurrences was 0.
        :raises: **ta_measurements.exceptions.TooManyFieldValuesFulfilingQuery** if number of occurrences was greater than 1.
        """
        query = message_query_parser().parse(input=expression)["action_result"]
        active_meas = self.get_active_measurements(ue_alias)
        logging.getLogger("ta_measurements").debug("Analyzing measurements:\n{}".format(active_meas))
        meas_to_check = self._get_meas_type_to_check(meas_type, active_meas)
        logging.getLogger("ta_measurements").debug("Analyzing {} measurements:\n{}".format(meas_type, meas_to_check))
        found, exact_meas = self._get_number_of_query_matching_measurements(query, meas_to_check)

        if found == 0:
            raise TooLittleFieldValuesFulfilingQuery(
                "No '{meas_type}' found fulfilling expression {expr}".format(meas_type=meas_type, expr=expression)
            )
        if found > 1:
            raise TooManyFieldValuesFulfilingQuery(
                "Found {found} '{meas_type}' fulfilling expression {expr}. "
                "Please tighten expression criteria".format(found=found, meas_type=meas_type, expr=expression)
            )

        return exact_meas.get_value_by_unique_key(field_name)

    def get_field_value_from_meas_type_with_expression_from_specific_measurement(
        self, field_name, meas_type, expression, ue_alias, measurement
    ):
        """
        Does the same as method 'get_field_value_from_meas_type_with_expression' but on user provided measurement
        instead of active measurement.

        For use in Python rather than thru Robot Framework

        Python example::
            all_measurements = ta_measurements_instance.get_measurement_installation_history(ue_alias)
            previous_measurement = all_measurements[-2]
            a3_discovery_expression = "((eventA3 is present) and (reportOnLeave eq 'TRUE'))"
            a3_reportConfigId = ta_measurements_instance.get_field_value_from_meas_type_with_expression_from_specific_measurement(
            field_name='reportConfigId',
            meas_type='reportConfig',
            expression=a3_discovery_expression,
            ue_alias=ue_alias,
            measurement=measurement)
        :param field_name: Any valid field name that is present inside parsed measurement message (typically RRCConnectionReconfiguration).
        :type field_name: str
        :param meas_type: One of ['measObject', 'reportConfig', 'measId'].
        :type meas_type: str
        :param expression: Valid Query language expression.
        :type expression: str
        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param measurement: selected measurement from ue measurement history.
        :type measurement: ta_measurements.configuration.MeasurementConfiguration
        :returns: **field_name** value if exactly one occurrence of **field_name** inside **meas_type** that fulfils **expression** was found.
        :raises: **ta_measurements.exceptions.TooLittleFieldValuesFulfilingQuery** if number of occurrences was 0.
        :raises: **ta_measurements.exceptions.TooManyFieldValuesFulfilingQuery** if number of occurrences was greater than 1.
        """
        query = message_query_parser().parse(input=expression)["action_result"]
        logging.getLogger("ta_measurements").debug("Analyzing measurements:\n{}".format(measurement))
        meas_to_check = self._get_meas_type_to_check(meas_type, measurement)
        logging.getLogger("ta_measurements").debug("Analyzing {} measurements:\n{}".format(meas_type, meas_to_check))

        found, exact_meas = self._get_number_of_query_matching_measurements(query, meas_to_check)

        if found == 0:
            raise TooLittleFieldValuesFulfilingQuery(
                "No '{meas_type}' found fulfilling expression {expr}".format(meas_type=meas_type, expr=expression)
            )
        if found > 1:
            raise TooManyFieldValuesFulfilingQuery(
                "Found {found} '{meas_type}' fulfilling expression {expr}. "
                "Please tighten expression criteria".format(found=found, meas_type=meas_type, expr=expression)
            )

        return exact_meas.get_value_by_unique_key(field_name)

    @keyword("Verify if ${ue_alias} has ${more|less} active measurements fulfilling ${expression}")
    def measurements_added(self, ue_alias, direction, expression):
        """
        Checks user query (using Query language: https://gitlabe1.ext.net.nokia.com/abstract_library/ta_messaging/wikis/query-language)
        against currently and previously active measurements. Verifies if the number of matches has changed.

        Robot Framework example::

            Verify if UE_1 has less configured measurements fulfilling (eventID eq eventA2)

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param direction: direction of validation - are we expecting more or less matches
        :type direction: str
        :param expression: Valid Query language expression.
        :type expression: str

        :return: None
        :raise: ArgumentError : if direction isn't more or less
        :raises: AssertionError : if previous amount of matches is bigger/smaller than the current one
        """
        meas_config = self.get_measurement_installation_history(ue_alias)
        assert len(meas_config) > 1, "No measurement history gathered - unable to run comparison"
        latest_meas_config = meas_config[-1].activeConfigs
        previous_meas_config = meas_config[-2].activeConfigs
        query = message_query_parser().parse(input=expression)["action_result"]

        latest_amount, latest_matches = self._get_number_of_query_matching_measurements(query, latest_meas_config)
        previous_amount, previous_matches = self._get_number_of_query_matching_measurements(query, previous_meas_config)
        if direction.lower() == "more":
            assert previous_amount < latest_amount
        elif direction.lower() == "less":
            assert previous_amount > latest_amount
        else:
            raise ArgumentError("direction should be either more or less")

    @keyword("Verify if ${expression} is active on ${ue_alias}")
    def event_configured(self, expression, ue_alias):
        """
        Checks if given query has matches in active measurements

        Robot Framework example::

            Verify if (eventA3 is present) is active on UE_1

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param expression: Valid Query language expression.
        :type expression: str

        :return: None
        :raises: AssertionError : if amount of matches is 0
        """
        meas_config = self.get_active_measurements(ue_alias)
        meas_config_full = meas_config.activeConfigs
        query = message_query_parser().parse(input=expression)["action_result"]
        amount, matches = self._get_number_of_query_matching_measurements(query, meas_config_full)
        assert amount > 0

    @keyword("Verify if ${event_name} is not active on ${ue_alias}")
    def event_not_configured(self, expression, ue_alias):
        """
        Checks if given query has no matches in active measurements

        Robot Framework example::

            Verify if (eventA3 is present) is not active on UE_1

        :param ue_alias: Alias created using `ta_messaging.create_ue_alias` method.
        :type ue_alias: str
        :param expression: Valid Query language expression.
        :type expression: str

        :return: None
        :raises: AssertionError : if amount of matches isn't 0
        """
        meas_config = self.get_active_measurements(ue_alias)
        meas_config_full = meas_config.activeConfigs
        query = message_query_parser().parse(input=expression)["action_result"]
        amount, matches = self._get_number_of_query_matching_measurements(query, meas_config_full)
        assert amount == 0

    def _get_meas_manager_for_ue_alias(self, ue_alias):
        try:
            return self.meas_managers[ue_alias]
        except KeyError:
            self.stop_observing_measurements()
            raise MeasurementsNotStarted("For '%s'" % ue_alias)

    def _get_meas_type_to_check(self, meas_type, active_meas):
        if meas_type == "measObject":
            return active_meas.measObjects
        elif meas_type == "reportConfig":
            return active_meas.reportConfigs
        elif meas_type == "measId":
            return active_meas.measIds
        else:
            raise WrongMeasurementType(
                "Provided meas_type should be one of: {}. Not {}".format(SUPPORTED_MEAS_TYPE_TO_CHECK, meas_type)
            )

    def _get_number_of_query_matching_measurements(self, query, meas_to_check):
        found = 0
        exact_meas = None
        logging.getLogger("ta_measurements").debug("Analyzing  of {} measurements".format(len(meas_to_check)))
        for measurement in meas_to_check.values():
            try:
                if query(measurement):
                    logging.getLogger("ta_measurements").debug("Query matched on measurement:\n{}".format(measurement))
                    found += 1
                    exact_meas = measurement
                else:
                    logging.getLogger("ta_measurements").debug("Query failed on measurement:\n{}".format(measurement))
            except NotFoundKey:
                logging.getLogger("ta_measurements").debug("Query failed on measurement:\n{}".format(measurement))
                continue
        return (found, exact_meas)

    def _end_test(self, name, attr):
        self.stop_observing_measurements()
